import{_ as i,a0 as l,w as d,s as o,I as n,x as a,a1 as t,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"ZOMBIES：软件开发和测试中的构建与拓展（二） | LCTT x X-CMD","titleTemplate":false,"description":"ZOMBIES：软件开发和测试中的构建与拓展（二） | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ZOMBIES：软件开发和测试中的构建与拓展（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ZOMBIES：软件开发和测试中的构建与拓展（二） | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20210202 How I build and expand application development and testing","title":"ZOMBIES：软件开发和测试中的构建与拓展（二）","tag":"202305","desc":""},"relativePath":"202305/20210202 How I build and expand application development and testing.md","filePath":"[post].md"}'),c={name:"202305/20210202 How I build and expand application development and testing.md"};function h(g,s,u,b,k,m){const e=l("Link");return d(),o("div",null,[s[18]||(s[18]=n("h1",{id:"zombies-软件开发和测试中的构建与拓展-二",tabindex:"-1"},[a("ZOMBIES：软件开发和测试中的构建与拓展（二） "),n("a",{class:"header-anchor",href:"#zombies-软件开发和测试中的构建与拓展-二","aria-label":"Permalink to “ZOMBIES：软件开发和测试中的构建与拓展（二）”"},"​")],-1)),s[19]||(s[19]=n("blockquote",null,[n("p",null,"在开发初期只对单个元素进行编码和测试，之后再拓展到多个元素上。")],-1)),s[20]||(s[20]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/16/154949rgu89gbzpzp1p0et.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("在 ",-1)),t(e,{href:"https://linux.cn/article-15808-1.html"},{default:p(()=>[...s[0]||(s[0]=[a("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=a(" 中我已经解释了为什么把所有编程问题当作一群丧尸一次性处理是错误的。我也解释了 ZOMBIES 方法中的第一条：最简场景。本文中我将进一步介绍接下来的两条：单元素场景和多元素场景。",-1))]),s[21]||(s[21]=r(`<p>ZOMBIES 表示以下首字母缩写：</p><ul><li><strong>Z</strong> – 最简场景（Zero）</li><li><strong>O</strong> – 单元素场景（One）</li><li><strong>M</strong> – 多元素场景（Many or more complex）</li><li><strong>B</strong> – 边界行为（Boundary behaviors）</li><li><strong>I</strong> – 接口定义（Interface definition）</li><li><strong>E</strong> – 处理特殊行为（Exercise exceptional behavior）</li><li><strong>S</strong> – 简单场景用简单的解决方案（Simple scenarios, simple solutions）</li></ul><p>在上一篇文章中，通过应用了最简场景，你在代码里构建了一条最简可行通路。这个代码里没有任何业务处理逻辑。现在是时候向系统中添加一个元素了。</p><p>最简场景表示系统中什么也没有，这是一个空的用例，我们什么也不用关心。单元素场景代表我们有一个元素需要关心考虑。这个单一元素可能是集合中的一个元素、一个访问着或者一个需要处理的事件。</p><p>对于多元素场景，我们需要处理更复杂的情况，比如两个或更多的集合元素或事件。</p><h3 id="单元素场景" tabindex="-1">单元素场景 <a class="header-anchor" href="#单元素场景" aria-label="Permalink to “单元素场景”">​</a></h3><p>在上一篇文章的代码基础上，向虚拟购物筐里添加一些商品。首先，写一个伪测试：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add1ItemBasketHas1Item() {</span></span>
<span class="line"><span>        var expectedNoOfItems = 1;</span></span>
<span class="line"><span>        var actualNoOfItems = 0;</span></span>
<span class="line"><span>        Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>不出所料，这个测试失败了，因为硬编码了一个错误的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Starting test execution, please wait...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A total of 1 test files matched the specified pattern.</span></span>
<span class="line"><span>[xUnit.net 00:00:00.57] tests.UnitTest1.NewlyCreatedBasketHas0Items [FAIL]</span></span>
<span class="line"><span>  X tests.UnitTest1.NewlyCreatedBasketHas0Items [4ms]</span></span>
<span class="line"><span>  Error Message:</span></span>
<span class="line"><span>   Assert.Equal() Failure</span></span>
<span class="line"><span>Expected: 0</span></span>
<span class="line"><span>Actual: 1</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>现在是时候停止伪造了。现在你已经用 <code>ArrayList</code> 实现了购物筐。那么应该怎么实现<em>商品</em>呢？</p><p>简洁性应该一直是你的指导原则。在不了解商品的太多信息的情况下，你可以先用另一个集合来实现它。这个表示商品的集合应该包含些什么呢？由于你多半会关心计算购物筐中的商品总价，所以对商品的表示至少需要包含价格（可以是任意货币，为简单起见，不妨假设是人民币）。</p><p>（我们需要）一个简单的集合类型，它包含一个商品 ID（可以在系统中的其它地方使用 ID 来指向该商品）和这个商品的价格。</p><p>键值对类型的数据结构可以很容易满足这个需求。在 C# 中最先被想到的数据结构就是 <code>Hashtable</code>。</p><p>在购物应用的代码中给 <code>IShoppingAPI</code> 增加一个新功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int AddItem(Hashtable item);</span></span></code></pre></div><p>这个新功能以一个用 <code>Hashtable</code> 表示的商品为输入，返回购物筐中的商品数量。</p><p>将测试代码中硬编码的值提替换为对接口的调用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add1ItemBasketHas1Item() {            </span></span>
<span class="line"><span>    var expectedNoOfItems = 1;</span></span>
<span class="line"><span>    Hashtable item = [new][3] Hashtable();</span></span>
<span class="line"><span>    var actualNoOfItems = shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>    Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的代码中实例化了一个 <code>Hashtable</code> 并命名为 <code>item</code>，然后调用购物接口中的 <code>AddItem(item)</code> 方法，该方法会返回购物筐中实际的商品数量。</p><p>转到 <code>ShoppingAPI</code> 类中，实现这个方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public int AddItem(Hashtable item) {</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里再次通过写假代码来检验测试的效果（测试是业务代码的第一个调用者）。如果测试失败，将硬编码值换成实际的代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public int AddItem(Hashtable item) {</span></span>
<span class="line"><span>    basket.Add(item);</span></span>
<span class="line"><span>    return basket.Count;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的代码中，向购物筐里添加了一件商品，然后返回购物筐中的商品数量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Test Run Successful.</span></span>
<span class="line"><span>Total tests: 2</span></span>
<span class="line"><span>     Passed: 2</span></span>
<span class="line"><span> Total time: 1.0633 Seconds</span></span></code></pre></div><p>到目前为止，你通过了两个测试，同时也基本里解了 ZOMBIES 方法中的最简场景和单元素场景两部分。</p><h3 id="反思总结" tabindex="-1">反思总结 <a class="header-anchor" href="#反思总结" aria-label="Permalink to “反思总结”">​</a></h3><p>回顾前面所做的工作，你会发现通过将注意力集中到处理最简场景和单元素场景上，你在构建接口的同时也定义了一些业务逻辑边界！这不是很棒吗？现在你已经部分地实现了最关键的抽象逻辑，并且能够处理什么也没有和只有一个元素的的情况。因为你正在构建的是一个电子交易 API，所以你不能对顾客的购物行为预设其它限制。总而言之，虚拟购物筐应该是无限大的。</p><p>ZOMBIES 提供的逐步优化思路的另一个重要方面（虽然不是很明显）是从大概思路到具体实现的阻力。你也许已经注意到了，要具体实现某个东西总是困难重重。倒不如先用硬编码值来构造一个伪实现。只有看到接口与测试之间以一种合理的方式交互之后，你才会愿意开始完善实现代码。</p><p>即便如此，你也应该采用简单直接的代码结构，尽可能避免条件逻辑分支。</p><h3 id="多元素场景" tabindex="-1">多元素场景 <a class="header-anchor" href="#多元素场景" aria-label="Permalink to “多元素场景”">​</a></h3><p>通过定义顾客向购物筐里添加两件商品时的期望来拓展应用程序。首先构造一个伪测试。它的期望值为 2，但是现在将实际值硬编码为 0，强制让测试失败：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsBasketHas2Items() {</span></span>
<span class="line"><span>        var expectedNoOfItems = 2;</span></span>
<span class="line"><span>        var actualNoOfItems = 0;</span></span>
<span class="line"><span>        Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>执行测试，前两个测试用例通过了（针对最简场景和单元素场景的测试），而硬编码的测试不出所料地失败了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A total of 1 test files matched the specified pattern.</span></span>
<span class="line"><span>[xUnit.net 00:00:00.57] tests.UnitTest1.Add2ItemsBasketHas2Items [FAIL]</span></span>
<span class="line"><span>  X tests.UnitTest1.Add2ItemsBasketHas2Items [2ms]</span></span>
<span class="line"><span>  Error Message:</span></span>
<span class="line"><span>   Assert.Equal() Failure</span></span>
<span class="line"><span>Expected: 2</span></span>
<span class="line"><span>Actual: 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Test Run Failed.</span></span>
<span class="line"><span>Tatal tests: 3</span></span>
<span class="line"><span>     Passed: 2</span></span>
<span class="line"><span>     Failed: 1</span></span></code></pre></div><p>将硬编码值替换为实际的代码调用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsBasketHas2Items() {</span></span>
<span class="line"><span>        var expectedNoOfItems = 2;</span></span>
<span class="line"><span>        Hashtable item = [new][3] Hashtable();</span></span>
<span class="line"><span>        shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>        var actualNoOfItems = shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>        Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个测试中，你向购物筐中添加了两件商品（实际上是将同一件商品添加了两次），然后比较期望的商品数量和第二次添加商品后调用 <code>shoppingAPI</code> 返回的商品数量是否相等。</p><p>现在所有测试都能够通过！</p><h3 id="敬请期待" tabindex="-1">敬请期待 <a class="header-anchor" href="#敬请期待" aria-label="Permalink to “敬请期待”">​</a></h3><p>现在你已经了解了最简场景、单元素场景和多元素场景。我将下一篇文章中介绍边界行为和接口定义。敬请期待!</p><p>（题图：MJ/e4679f1f-311a-4a41-80e8-8d2834b956f2）</p><hr>`,44)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/21/2/build-expand-software"},{default:p(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/21/2/build-expand-software",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/alex-bunardzic"},{default:p(()=>[...s[5]||(s[5]=[a("Alex Bunardzic",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),t(e,{href:"https://github.com/toknow-gh"},{default:p(()=>[...s[7]||(s[7]=[a("toknow-gh",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const v=i(c,[["render",h]]);export{x as __pageData,v as default};
